    let mut p_0 = P { x: -1000, y: true };
    if (read(&p_0) != -1000) { return 1; }
    if (bump(&mut p_0) != -998) { return 1; }
    if (p_0.x != -998) { return 1; }
    if (!p_0.y) { return 1; }
    let mut p_1 = P { x: 0, y: true };
    if (read(&p_1) != 0) { return 1; }
    if (bump(&mut p_1) != 2) { return 1; }
    if (p_1.x != 2) { return 1; }
    if (!p_1.y) { return 1; }
    let mut p_2 = P { x: 1000000, y: true };
    if (read(&p_2) != 1000000) { return 1; }
    if (bump(&mut p_2) != 1000002) { return 1; }
    if (p_2.x != 1000002) { return 1; }
    if (!p_2.y) { return 1; }
    return print("accepted\n");
}

